from author import *
c=C('操作系统概述与运行机制')
S(c,'课程导学与十章知识地图',[T('学习路线','先认对象，再看状态，最后按步骤计算'),T('课程重点','408核心概念、典型算法与基础题型')],[P('这一小时，我们从一台电脑同时运行几个程序开始，把操作系统的常见考点串起来。先分清进程、线程和调度，再处理同步、死锁、内存、文件与输入输出。每个新词都配具体场景，计算题按表格一步步做。每章有一道暂停练习，先自己判断，再看下一页答案。本课搭建基础框架，完整复习还要结合考试大纲和往年题。',[1,2],['先理解题设，再套算法','练习时可以暂停多想一会儿'])],[],kind='overview')
S(c,'操作系统管理什么',[T('处理器','决定哪个任务在什么时候运行'),T('内存与外存','管理运行空间和长期保存的数据'),T('设备与接口','统一管理设备，提供可用的服务')],[P('先看应用程序、操作系统、硬件这三层。应用想计算，需要处理器；想保存内容，需要磁盘；想显示窗口，需要设备。操作系统负责协调这些资源，让多个程序按规则使用它们。浏览器通常不直接随意修改磁盘控制器，而是通过操作系统提供的接口请求服务。做概念题时，把管理资源和提供接口这两种职责一起记住。',[1,2],['应用请求服务，内核管理资源','磁盘上的文件不等于内存中的运行空间'],phase='layers',anchor='先看应用程序'),P('从使用者的角度看，系统把复杂的设备操作包装成打开、读取、写入等接口。从管理者的角度看，它还要处理隔离、保护和共享。共享不表示任何程序都能任意访问任何数据，而是在授权和协调下使用资源。考试问操作系统是不是普通应用软件，答案是否定的；它是管理计算机资源、控制程序执行的系统软件。',[3],['共享有规则，访问有权限','接口简化使用，保护限制越界'],phase='service',anchor='从使用者的角度看')],['操作系统功能'],visual=G('layers'))
S(c,'并发、并行与系统特征',[T('并发','一段时间内，多个任务交替推进'),T('并行','同一时刻，多个任务同时执行'),T('四个常见特征','并发、共享、虚拟、异步')],[P('在单处理机的简化题设里，先运行浏览器一小段，再运行播放器一小段，两项工作在同一段时间里都得到推进，这叫并发。',[1,2],['看一段时间，还是看同一时刻','有多个任务，不代表此刻同时执行'],phase='concurrent',anchor='先运行浏览器一小段'),P('如果有两个可同时执行的处理单元，同一时刻分别运行两项工作，才是并行。不要看到屏幕上开了两个窗口，就直接判断存在并行；题目还要给出硬件和执行条件。其余三个特征也用具体事情记。共享是多个任务按规则使用同一资源；虚拟是把物理资源抽象成更方便使用的逻辑资源，例如进程自己的地址空间。异步是各程序推进速度无法事先固定，因为资源获取和外部事件会影响它们。异步不表示毫无约束，系统仍然通过同步机制保证需要的先后关系。',[3],['虚拟强调逻辑视图','异步推进仍需满足同步约束'],phase='parallel',anchor='如果有两个可同时执行的处理单元')],['并发与并行','操作系统特征'],visual=G('cpu_lanes'))
S(c,'批处理、分时与实时系统',[T('批处理','成批提交任务，重视吞吐和资源利用'),T('分时','轮流响应交互用户，重视响应速度'),T('实时','在规定时间内完成处理，重视时限')],[P('比较系统类型时，先问它最关心什么。批处理把任务交给系统排队执行，用户不必全程交互，通常重视一段时间内完成多少工作。分时让多个用户或任务轮流获得短时间服务，重视交互响应。两者都可能采用多道程序技术，不能把多道程序简单等同于分时，也不能说批处理绝对没有任何调度。',[1,2],['吞吐量和响应时间不是同一个指标','技术手段与系统类型不要混同']),P('实时系统的关键是处理结果必须在要求的时限内产生。硬实时强调不能错过关键截止时间，软实时允许一定程度的超时影响服务质量。它不只是平均运行得快，而是关注时限约束。题目同时提到快速和实时，先找有没有明确截止要求，再判断对应目标，避免只凭快这个词作选择。',[3],['实时关注截止时间','平均快，不等于满足每次时限'])],['系统类型与目标'])
S(c,'用户态、内核态与系统调用',[T('用户态','受限执行，不能随意使用特权指令'),T('内核态','内核可执行受保护的资源管理操作'),T('系统调用','应用主动请求内核服务的入口')],[P('把用户态和内核态看成处理器当前的权限级别。普通应用主要在用户态运行，不能随意关闭中断或改写受保护的管理数据。需要打开文件时，库函数可能先做参数处理，再通过系统调用进入内核。进入内核之后，还是可能在为同一个进程服务，因此一次用户态到内核态的转换，不一定意味着切换到另一个进程。',[1,2],['态转换是权限变化','进程切换是执行主体变化'],phase='user',anchor='普通应用主要在用户态运行'),P('系统调用是请求操作系统服务的接口，不等于所有普通函数调用。数学库中一次纯计算函数调用，可能全程留在用户态；读取文件的库接口则可能封装系统调用。应用通过规定的入口进入内核，完成服务后再返回。不能因为应用发出了请求，就说它自己获得了任意执行特权指令的资格。',[3],['普通函数调用不一定进入内核','系统调用入口由硬件和内核共同约束'],phase='kernel',anchor='通过规定的入口进入内核')],['运行态与系统调用'],visual=G('mode_switch'))
S(c,'中断、异常与系统结构',[T('外部中断','例如时钟和设备完成通知'),T('异常与陷入','例如缺页、非法指令和系统调用入口'),T('结构与启动','内核组织、虚拟机与引导过程')],[P('按常见考试分类，外部中断来自处理器外部，例如时钟到期、设备完成。异常与当前执行的指令有关，例如除法出错、访问尚未调入的页面。系统调用通常通过专门的陷入指令进入内核。判断时先看事件来源，不要把所有进入内核的事件都叫外部中断。发生中断后要保存必要现场，处理完再决定恢复谁。',[1,2],['按来源区分外部中断和内部异常','缺页是异常，不是TLB未命中'],phase='interrupt',anchor='设备完成'),P('结构题先抓边界。宏内核把较多服务放在内核空间，微内核只保留较小核心，其余服务可以通过消息交互。虚拟机监控器则在真实硬件和客户系统之间提供虚拟硬件环境。启动时先由固件和引导程序加载内核，再建立运行环境；不能说按下电源后，普通应用就能越过这些步骤直接控制硬件。',[3],['结构取舍看服务放在哪里','虚拟机不是简单复制一个应用窗口'],phase='structure',anchor='微内核只保留较小核心')],['中断异常','内核结构与启动'],visual=G('kernel_structure'))
S(c,'概念辨析练习',[T('场景','单处理机交替运行A、B；A请求读取文件'),T('判断一','A、B交替运行是否属于并行？'),T('判断二','A进入内核态是否必然发生进程切换？')],[P('暂停判断两句话。第一，单处理机在A和B之间交替运行，因此属于并行。第二，A为了读取文件进入内核态，因此一定切换到了另一个进程。每句话分别判断正误，并说出你采用的区分标准。不要把一段时间内都在推进，误读成同一时刻同时执行。',[1,2,3],['区分并发与并行','区分态转换与进程切换'])],['概述练习'],kind='question')
S(c,'概念辨析练习答案',[T('第一句错误','交替推进是并发，题设未形成同时执行'),T('第二句错误','进入内核可以继续为进程A服务'),T('检查方法','分别看时间尺度、权限和执行主体')],[P('两句话都错。单处理机交替执行体现的是并发，不是同时执行。A进入内核态说明执行权限发生变化，但内核此时可以继续为A处理读取请求，并不必然切到B。只有确实更换了正在运行的进程，才讨论进程切换。这两个区分点后面还会用于理解调度、中断和阻塞。',[1,2,3],['并发不要求多个执行单元','一次系统调用不必然换进程'])],['概述练习'],kind='answer')
c=C('进程、线程与状态转换')
S(c,'程序与进程',[T('程序','存放在外存中的指令和静态数据'),T('进程','程序的一次运行活动及其资源环境'),T('PCB','记录进程身份、状态和管理信息')],[P('程序像一份可反复使用的菜谱，进程像按照菜谱正在进行的一次做饭活动。同一个程序可以运行多次，产生不同进程；每次运行的数据和状态不必相同。进程需要代码、数据、栈和管理信息，操作系统通过进程控制块，也就是PCB，跟踪它是谁、运行到哪里、占用哪些资源。不要把磁盘上的一个文件直接当成一个正在运行的进程。',[1,2],['同一程序可以对应多个进程','进程是动态的运行活动'],phase='launch',anchor='同一个程序可以运行多次'),P('PCB不是程序代码本身。它记录进程标识、状态、处理器现场和资源管理等信息。进程切出去时，把必要寄存器状态保存下来；轮到它继续执行时，再恢复现场。进程的内存映像则包括代码、数据、堆和栈等区域。题目问哪个结构用于管理和描述进程，优先想到PCB，别把它与页表或普通文件目录混在一起。',[3],['PCB描述和管理进程','寄存器现场帮助恢复执行'],phase='pcb',anchor='把必要寄存器状态保存下来')],['程序与进程','PCB'],visual=G('process_image'))
S(c,'就绪、运行与阻塞',[T('就绪','运行条件已具备，只等待处理器'),T('运行','正在处理器上执行'),T('阻塞','等待I/O、资源或同步事件')],[P('先给三种状态各找一句判断口令。就绪是万事俱备，只差处理器；运行是此刻正在执行；阻塞是还有别的条件没满足，光给处理器也无法继续。例如进程请求读磁盘，数据还没到，它可能进入阻塞。进程的时间片用完，但仍有工作可以做，则通常回到就绪，而不是阻塞。先区分缺处理器还是缺事件。',[1,2,3],['就绪只差处理器','阻塞还缺资源或事件'],phase='ready_run',anchor='时间片用完'),P('现在沿箭头检查转换。调度把就绪变成运行；等待事件使运行变成阻塞；事件完成把阻塞变成就绪。阻塞解除并不代表马上占用处理器，仍需经过调度。若题目增加创建、终止或挂起状态，再按具体事件扩展，但不要因此丢掉三态模型的基本含义。选择题里的阻塞直接变运行，是常见混淆点。',[1,2,3],['事件完成先进入就绪','能运行和正在运行不同'],phase='block_wake',anchor='事件完成把阻塞变成就绪')],['进程状态转换'],visual=G('process_states'))
S(c,'创建、撤销与上下文切换',[T('创建','分配标识和资源，建立管理信息'),T('切换','保存旧现场，选择并恢复新现场'),T('终止','释放应回收资源，维护相关关系')],[P('创建进程不仅是把状态字改成就绪，还要建立身份、分配所需资源和管理结构。进程终止时，则要按系统规则回收资源，处理父子关系和未完成的管理事项。进程在运行中可能创建子进程，但子进程并不是父进程的一条普通函数调用。它有自己的执行状态，操作系统可以分别调度它们。',[1,3],['创建伴随资源与管理结构建立','进程终止与普通函数返回不同']),P('进程切换可以想成暂存一份执行记录，再打开另一份记录继续做。保存内容包括必要的寄存器和运行位置；地址空间相关状态也可能需要调整。切换本身有开销，不是在替用户程序完成有用计算。因此时间片越短，交互响应可能改善，但切换成本也可能增加。题目若忽略切换开销，才按理想时间线直接计算。',[2],['切换会消耗时间','计算前检查是否忽略开销'])],['进程控制','上下文切换'])
S(c,'线程共享什么、独有什么',[T('共享','同一进程内的代码、全局数据、堆等'),T('独有','线程的寄存器现场、栈、标识等'),T('作用','把一个进程中的执行流拆分开')],[P('把进程看成一个工作室，线程是里面分别做事的工作人员。它们可以使用同一进程的代码和全局数据，也能访问共享的堆空间；但每条执行流都需要自己的运行位置、寄存器现场和栈。共享数据带来协作方便，也会带来竞争。线程不是把进程的全部资源再完整复制一遍，不能把线程栈与进程共享堆互换。',[1,2],['同进程线程可共享地址空间','每条执行流仍要保存自己的现场'],phase='shared',anchor='使用同一进程的代码'),P('在支持内核线程的常见模型中，内核可以把线程作为调度对象。多个线程可以并发，也可能在多个执行单元上并行。一个线程修改共享变量，其他线程可能看见变化，因此共享并不等于自动安全；后面要靠互斥和同步约束访问。不同进程通常地址空间隔离，不能把同一个数值地址直接当成同一份物理数据。',[3],['共享数据需要同步保护','相同逻辑地址不保证相同物理位置'],phase='private',anchor='一个线程修改共享变量')],['线程与进程区别'],visual=G('threads'))
S(c,'用户级线程与内核级线程',[T('用户级线程','由用户空间线程库参与管理'),T('内核级线程','内核知道并能够调度的执行对象'),T('映射模型','多对一、一对一、多对多')],[P('先看内核能看见谁。用户级线程可以由线程库在用户空间切换，某些切换不需要进入内核；内核级线程则由内核管理和调度。多对一模型把多个用户线程映射到一个内核调度实体，在多核上也不能仅凭这些用户线程实现真正并行。一个阻塞系统调用还可能使整个实体停住，具体行为要按题设的线程实现判断。',[1,2],['先找内核能够调度的对象','多对一的并行能力受到限制'],phase='many_one',anchor='多对一模型'),P('一对一让每个用户线程对应一个内核线程，内核可以分别调度，但管理成本也会增加。多对多允许多个用户线程映射到多个内核线程。考试不是问哪个名称听起来更高级，而是比较并行能力、阻塞影响和管理开销。题目没有指定映射模型时，不要直接断言一个线程阻塞就必然让该进程中所有线程全部阻塞。',[3],['并行能力和开销一起比较','阻塞影响要结合具体映射模型'],phase='one_one',anchor='一对一让每个用户线程')],['线程映射模型'],visual=G('thread_mapping'))
S(c,'通信、信号与进程关系',[T('共享存储','共享数据区，需要另外协调访问'),T('消息与管道','传递内容，按接口语义读写'),T('信号','通知事件，不等于信号量')],[P('进程通信常见三类。共享存储让双方访问约定的数据区，但谁先写、谁后读仍需要同步。消息传递由接口发送和接收内容。管道提供字节流通道，普通匿名管道常按半双工理解，具体方向和阻塞行为以题目为准。共享存储也不表示操作系统完全不参与；建立、映射和权限控制仍有管理过程。',[1,2],['共享数据区不自动保证先后顺序','管道方向、容量和阻塞看题设']),P('信号是事件通知机制，信号量则是后面用于同步互斥的计数机制，中文名字相近，不能当成同一个概念。再看一个创建计数题：假设所有创建都成功，每个现有进程都继续执行两轮创建，每轮都再产生一个子进程，数量依次是一变二、二变四，总共四个进程。如果只让原父进程创建，答案就不同，必须先确定谁继续执行。',[3],['信号不等于信号量','创建数量先确定哪些分支继续'])],['进程通信','信号','进程创建计数'])
S(c,'状态转换练习',[T('题设','进程P等待磁盘数据，当前处于阻塞'),T('事件','磁盘读取完成，处理器正在运行Q'),T('问题','P通常先转为什么状态？')],[P('暂停判断。进程P正在等待磁盘数据，属于阻塞；现在读取完成，而处理器仍在运行Q。P通常先变成就绪，还是直接变成运行？请用状态含义解释，不要只记住箭头方向。再想一想，若P只是时间片用完，它从运行离开时又该进入哪种状态。',[1,2,3],['事件完成不等于已经获得处理器','时间片用完不等于等待事件'])],['进程状态练习'],kind='question')
S(c,'状态转换练习答案',[T('读取完成','阻塞 → 就绪'),T('时间片用完','运行 → 就绪'),T('等待新事件','运行 → 阻塞')],[P('读取完成后，P具备继续执行的条件，先进入就绪队列，是否马上运行还要看调度。时间片用完时，进程通常也回到就绪，因为它并不缺少其他事件条件。只有需要等待输入输出、资源或同步事件时，才讨论阻塞。两种就绪来源不同，但共同点都是已经能够继续，只是在等处理器。',[1,2,3],['就绪表示能继续，但还没执行','阻塞必须找到正在等什么'])],['进程状态练习'],kind='answer')

